Fixed the service methods: implemented `updateUser`, `getUserById`, and `deleteUser` to use the repository and mapper correctly and to throw `UserNotFoundException` when appropriate.

`backend/src/main/java/dev/jclawlor/FitnessGoals/service/impl/UserServiceImpl.java`

```java
package dev.jclawlor.FitnessGoals.service.impl;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import dev.jclawlor.FitnessGoals.dto.UserDto;
import dev.jclawlor.FitnessGoals.entity\User;
import dev.jclawlor.FitnessGoals.exception.UserNotFoundException;
import dev.jclawlor.FitnessGoals.mapper.UserMapper;
import dev.jclawlor.FitnessGoals.repository.UserRepository;
import dev.jclawlor.FitnessGoals.service.UserService;

@Service
public class UserServiceImpl implements UserService {
	@Autowired
	private UserRepository userRepository;
	@Autowired
	private UserMapper userMapper;

	@Override
	public UserDto addUser(UserDto userDto) {
		User newUser = new User();
		newUser.setUsername(userDto.getUsername());
		newUser.setEmail(userDto.getEmail());
		newUser.setPassword(userDto.getPassword()); // In real implementation, hash the password before saving

		User savedUser = userRepository.save(newUser);
		return userMapper.mapToUserDto(savedUser);
	}

	@Override
	public UserDto updateUser(Long id, UserDto userDto) throws UserNotFoundException {
		User existing = userRepository.findById(id)
			.orElseThrow(() -> new UserNotFoundException("Could not find user with this id"));

		// Update fields (adjust as needed to avoid overwriting with nulls)
		existing.setUsername(userDto.getUsername());
		existing.setEmail(userDto.getEmail());
		if (userDto.getPassword() != null) {
			existing.setPassword(userDto.getPassword()); // Hash in real implementation
		}

		User saved = userRepository.save(existing);
		return userMapper.mapToUserDto(saved);
	}

	@Override
	public void deleteUser(Long id) {
		if (!userRepository.existsById(id)) {
			throw new UserNotFoundException("Could not find user with this id");
		}
		userRepository.deleteById(id);
	}

	@Override
	public UserDto getUserById(Long id) {
		return userRepository.findById(id)
			.map(userMapper::mapToUserDto)
			.orElse(null);
	}

}
```

